// A Verus‐verified implementation of nanargmax for a non‐empty Vec<i8>.

#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

    /// Given a non‐empty array `a` of signed 8‐bit integers,
    /// returns the index of the first occurrence of the maximal element.
    ///
    /// Requirements:
    ///  1. `a.len() > 0`
    ///
    /// Guarantees:
    ///  1. `idx < a.len()`
    ///  2. ∀ i < a.len(): a[idx] ≥ a[i]
    ///  3. ∀ j < idx: a[j] < a[idx]
    pub fn nanargmax(a: Vec<i8>) -> (idx: usize)
        requires
            a.len() > 0,
        ensures
            idx < a.len(),
        ensures
            forall |i: usize| i < a.len() ==> a[idx] >= a[i],
        ensures
            forall |j: usize| j < idx ==> a[j] < a[idx],
    {
        // cur = index of the maximum so far in a[0..i)
        let mut cur: usize = 0;
        // i = next position to inspect
        let mut i: usize = 1;

        // Loop until we've inspected all elements.
        while i < a.len() {
            // Invariants to carry through the loop:
            //  1. i is in range [1, a.len()]
            //  2. cur < a.len()
            //  3. cur < i
            //  4. for all k < i, a[cur] ≥ a[k]
            invariant
                1 <= i && i <= a.len(),
            invariant
                cur < a.len(),
            invariant
                cur < i,
            invariant
                forall |k: usize| k < i ==> a[cur] >= a[k],
            decreases
                a.len() - i;    // variant to prove termination
            {
                // If we find a strictly larger element, update cur.
                if a[i] > a[cur] {
                    cur = i;
                }
                i += 1;
            }
        }

        // After the loop, cur is the first index of the maximum.
        idx = cur;
    }
}